pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address owner;

    function setUp() public {
        c = new RoundFactory();
        owner = address(this);
        c.initialize();
    }

    function testFuzz_property(address newRoundImplementation) public {
        vm.assume(newRoundImplementation != address(0));

        c.updateRoundImplementation(payable(newRoundImplementation));

        assertTrue(c.roundImplementation() == newRoundImplementation);
    }
}
